            { "use": "content/prose", "key": "hours", "data": { "html": "<p>Hours: Monday–Saturday 9:00–19:00, Sunday 10:00–17:00.</p>" } }
          ] }
        },
        {
          "use": "content/section", "key": "form", "data": { "title": "Contact form" },
